mapper.select:
select 
       lay.layering_id, /*核算分层信息.分层代码*/
       lay.branch,/*分支序号*/
       lay.bok_detail_id,/*核算分层信息.账务明细代码*/
       lay.busi_id, /*核算分层信息.业务明细代码*/
       lay.busi_detail_type, /*核算分层信息.业务明细类型*/
       bok.bookset_id, /*账套.账套代码*/
       bok.standard_ccy /*账套.本位币*/
  from BOK_BOOKSET bok
 inner join BOK_BOOKSET_EXT ext
    on bok.bookset_id = ext.bookset_id
   and ext.param_code = #{paramCode}
   and ext.param_value = #{paramValue}
 inner join BOK_ACCT_LAYERING_INFO lay
    on bok.bookset_id = lay.bookset_id
 inner join BOK_BATCH_TASK_TODO todo
    on todo.task_id = #{taskId}
   and todo.bookset_date = #{booksetDate}
   and todo.happen_date = #{happenDate}
   and todo.book_date = #{bookDate}
   and todo.seq_no = #{seqNo,jdbcType=VARCHAR}
   and todo.bookset_id = bok.bookset_id

 WHERE bok.acct_mode = #{profitType,jdbcType=VARCHAR}

		select count(*) as amounts
		  from TRD_PRODUCT_DEAL trd, BOK_DEAL_ACCOUNTING acct
		 where trd.finprod_id = #{busiId}
		   and trd.finprod_type = #{busiDetailType}
		   and trd.branch = #{branch}
		   and trd.trade_date = #{happenDate}
		   and acct.busi_table = #{busiTable}
		   and acct.busi_no = trd.trade_id
		   and acct.bookset_id = #{booksetId}

   			   and trd.ps in 

   			   		#{item}

		select A.Trade_Id as tradeId
		  from TRD_PRODUCT_DEAL     A
		 inner join BOK_BATCH_TASK_TODO B
		    on B.task_id = #{taskId}
		   and B.bookset_date = #{booksetDate}
		   and B.happen_Date = #{happenDate}
		   and B.book_date = #{bookDate}
		   and B.seq_no =  #{seqNo}
		 inner join TRD_PRODUCT_DEAL_ADD D
		    on D.trade_Id = A.trade_Id
		   and D.GEN_TYPE = #{genType}
		 inner join BOK_DEAL_ACCOUNTING E
		    on E.Bookset_Id = B.Bookset_Id
		   and E.BUSI_TABLE = #{busiTable}
		   and E.Busi_No = A.Trade_Id
		 where A.Trade_Date = #{happenDate}

   			   and A.Busi_Type in 

   			   		#{item}

